              {
                "type": "number"
              },
              {
                "type": "number"
              },
              {
                "type": "number"
              }
            ],
            "title": "Size Nm",
            "type": "array"
          }
        },
        "required": [
          "size_nm"
        ],
        "title": "Box",
        "type": "object"
      },
      "Circle": {
        "additionalProperties": false,
