          },
          "center_nm": {
            "default": [
              0.0,
              0.0
            ],
            "maxItems": 2,
            "minItems": 2,
            "prefixItems": [
              {
                "type": "number"
              },
              {
                "type": "number"
              }
            ],
            "title": "Center Nm",
            "type": "array"
          },
          "radius_nm": {
            "exclusiveMinimum": 0,
            "title": "Radius Nm",
            "type": "number"
          }
        },
        "required": [
          "radius_nm"
        ],
        "title": "Circle",
        "type": "object"
      },
      "ConstantIndex": {
        "additionalProperties": false,
        "description": "Wavelength-independent complex refractive index n + ik.",
        "properties": {
          "kind": {
            "const": "constant_index",
            "default": "constant_index",
            "title": "Kind",
            "type": "string"
          },
          "n_real": {
            "description": "Real part of the refractive index.",
            "title": "N Real",
            "type": "number"
          },
          "n_imag": {
            "default": 0.0,
            "description": "Extinction coefficient k (>= 0 for loss).",
            "minimum": 0,
            "title": "N Imag",
            "type": "number"
          }
        },
        "required": [
          "n_real"
        ],
        "title": "ConstantIndex",
        "type": "object"
      },
      "ConstantPermittivity": {
        "additionalProperties": false,
        "description": "Wavelength-independent complex relative permittivity.",
        "properties": {
          "kind": {
            "const": "constant_permittivity",
            "default": "constant_permittivity",
            "title": "Kind",
            "type": "string"
          },
          "eps_real": {
            "title": "Eps Real",
            "type": "number"
          },
          "eps_imag": {
            "default": 0.0,
            "minimum": 0,
            "title": "Eps Imag",
            "type": "number"
          }
        },
        "required": [
          "eps_real"
        ],
        "title": "ConstantPermittivity",
        "type": "object"
      },
      "Drude": {
        "additionalProperties": false,
        "description": "eps(w) = eps_inf - wp^2 / (w^2 + i*gamma*w), energies in eV.",
        "properties": {
          "kind": {
            "const": "drude",
            "default": "drude",
            "title": "Kind",
            "type": "string"
          },
          "eps_inf": {
            "default": 1.0,
            "title": "Eps Inf",
            "type": "number"
          },
          "wp_ev": {
            "description": "Plasma frequency in eV.",
            "exclusiveMinimum": 0,
            "title": "Wp Ev",
            "type": "number"
          },
          "gamma_ev": {
            "description": "Damping rate in eV.",
            "minimum": 0,
            "title": "Gamma Ev",
            "type": "number"
          }
        },
        "required": [
          "wp_ev",
          "gamma_ev"
        ],
        "title": "Drude",
        "type": "object"
      },
      "DrudeLorentz": {
        "additionalProperties": false,
        "description": "eps(w) = eps_inf - wp^2/(w^2 + i g w) + sum_j d_j w0_j^2 / (w0_j^2 - w^2 - i G_j w).\n\nThe form FDTD needs for auxiliary-differential-equation dispersion.\nFit one to measured data with :func:`lightsmith.materials_fit.fit_drude_lorentz`.",
        "properties": {
          "kind": {
            "const": "drude_lorentz",
            "default": "drude_lorentz",
            "title": "Kind",
            "type": "string"
          },
          "eps_inf": {
            "default": 1.0,
            "title": "Eps Inf",
            "type": "number"
          },
          "wp_ev": {
            "default": 0.0,
            "minimum": 0,
            "title": "Wp Ev",
            "type": "number"
          },
          "gamma_ev": {
            "default": 0.0,
            "minimum": 0,
            "title": "Gamma Ev",
            "type": "number"
          },
          "poles": {
            "items": {
              "$ref": "#/$defs/LorentzPole"
            },
            "title": "Poles",
            "type": "array"
          }
        },
        "title": "DrudeLorentz",
        "type": "object"
      },
      "Ellipse": {
        "additionalProperties": false,
        "properties": {
          "kind": {
            "const": "ellipse",
            "default": "ellipse",
            "title": "Kind",
            "type": "string"
          },
          "center_nm": {
            "default": [
              0.0,
              0.0
            ],
            "maxItems": 2,
            "minItems": 2,
            "prefixItems": [
              {
                "type": "number"
              },
              {
                "type": "number"
              }
            ],
            "title": "Center Nm",
            "type": "array"
          },
          "semi_axes_nm": {
            "maxItems": 2,
            "minItems": 2,
            "prefixItems": [
              {
                "type": "number"
              },
              {
                "type": "number"
              }
            ],
            "title": "Semi Axes Nm",
            "type": "array"
          },
          "angle_deg": {
            "default": 0.0,
            "title": "Angle Deg",
            "type": "number"
          }
        },
        "required": [
          "semi_axes_nm"
        ],
        "title": "Ellipse",
        "type": "object"
      },
      "GdsLayout": {
        "additionalProperties": false,
        "description": "Import geometry from a GDS file: each layer/datatype is extruded with a material.",
        "properties": {
          "path": {
            "title": "Path",
            "type": "string"
          },
          "cell": {
            "anyOf": [
              {
                "type": "string"
              },
              {
                "type": "null"
              }
            ],
            "default": null,
            "title": "Cell"
          },
          "layer_map": {
            "additionalProperties": {
              "additionalProperties": true,
              "type": "object"
            },
            "description": "'layer/datatype' -> {'material': Material JSON, 'z_min_nm': .., 'z_max_nm': ..}",
            "title": "Layer Map",
            "type": "object"
          }
        },
        "required": [
          "path",
          "layer_map"
        ],
        "title": "GdsLayout",
        "type": "object"
      },
      "LibraryMaterial": {
        "additionalProperties": false,
        "description": "Measured n, k bundled with lightsmith, e.g. ``{\"kind\": \"library\", \"name\": \"Au\",\n\"dataset\": \"Johnson-Christy\"}``. Linear interpolation in n and k, no extrapolation.\n\nNames and datasets accept aliases (\"gold\", \"JC\") and are stored in canonical form;\nan omitted dataset is filled with the material's default so the spec stays\nreproducible. See :func:`list_materials`.",
        "properties": {
          "kind": {
            "const": "library",
            "default": "library",
            "title": "Kind",
            "type": "string"
          },
          "name": {
            "description": "Material, e.g. 'Au', 'Ag', 'Al', 'Cu', 'Si', 'TiO2', 'SiO2', 'H2O'.",
            "title": "Name",
            "type": "string"
          },
          "dataset": {
            "anyOf": [
              {
                "type": "string"
              },
              {
                "type": "null"
              }
            ],
            "default": null,
            "description": "Dataset, e.g. 'Johnson-Christy'; omitted = material default.",
            "title": "Dataset"
          }
        },
        "required": [
          "name"
        ],
        "title": "LibraryMaterial",
        "type": "object"
      },
      "LorentzPole": {
        "additionalProperties": false,
        "properties": {
          "delta_eps": {
            "description": "Oscillator strength (permittivity step).",
            "title": "Delta Eps",
            "type": "number"
          },
          "omega0_ev": {
            "description": "Resonance energy in eV.",
            "exclusiveMinimum": 0,
            "title": "Omega0 Ev",
            "type": "number"
          },
          "gamma_ev": {
            "description": "Damping in eV.",
            "minimum": 0,
            "title": "Gamma Ev",
            "type": "number"
          }
        },
        "required": [
          "delta_eps",
          "omega0_ev",
          "gamma_ev"
        ],
        "title": "LorentzPole",
        "type": "object"
      },
      "Polygon": {
        "additionalProperties": false,
        "properties": {
          "kind": {
            "const": "polygon",
            "default": "polygon",
            "title": "Kind",
            "type": "string"
          },
          "vertices_nm": {
            "items": {
              "maxItems": 2,
              "minItems": 2,
              "prefixItems": [
                {
                  "type": "number"
                },
                {
                  "type": "number"
                }
              ],
              "type": "array"
            },
            "minItems": 3,
            "title": "Vertices Nm",
            "type": "array"
          }
        },
        "required": [
          "vertices_nm"
        ],
        "title": "Polygon",
        "type": "object"
      },
      "Port": {
        "additionalProperties": false,
        "properties": {
          "name": {
            "title": "Name",
            "type": "string"
          },
          "center_nm": {
            "maxItems": 3,
            "minItems": 3,
            "prefixItems": [
              {
                "type": "number"
              },
              {
                "type": "number"
              },
              {
                "type": "number"
              }
            ],
            "title": "Center Nm",
            "type": "array"
          },
          "size_nm": {
            "description": "Zero along the port normal. In 2D devices z may also be zero, e.g. (0, w, 0) for an x-normal port.",
            "maxItems": 3,
            "minItems": 3,
            "prefixItems": [
              {
                "type": "number"
              },
              {
                "type": "number"
              },
              {
                "type": "number"
              }
            ],
            "title": "Size Nm",
            "type": "array"
          },
          "direction": {
            "description": "Direction of propagation *into* the device along the normal.",
            "enum": [
              "+",
              "-"
