            "title": "Direction",
            "type": "string"
          },
          "num_modes": {
            "default": 1,
            "minimum": 1,
            "title": "Num Modes",
            "type": "integer"
          }
        },
        "required": [
          "name",
          "center_nm",
          "size_nm",
          "direction"
        ],
        "title": "Port",
        "type": "object"
