      "Prism": {
        "additionalProperties": false,
        "description": "A 2D profile in the xy plane extruded from z_min to z_max (with optional sidewall angle).",
        "properties": {
          "kind": {
            "const": "prism",
            "default": "prism",
            "title": "Kind",
            "type": "string"
          },
          "profile": {
            "discriminator": {
