                "circle": "#/$defs/Circle",
                "ellipse": "#/$defs/Ellipse",
                "polygon": "#/$defs/Polygon",
                "rectangle": "#/$defs/Rectangle"
              },
              "propertyName": "kind"
            },
            "oneOf": [
              {
                "$ref": "#/$defs/Rectangle"
              },
              {
                "$ref": "#/$defs/Circle"
              },
              {
                "$ref": "#/$defs/Ellipse"
              },
              {
                "$ref": "#/$defs/Polygon"
              }
            ],
            "title": "Profile"
          },
          "z_min_nm": {
            "title": "Z Min Nm",
            "type": "number"
          },
          "z_max_nm": {
            "title": "Z Max Nm",
            "type": "number"
          },
          "sidewall_angle_deg": {
            "default": 0.0,
            "description": "0 = vertical; positive = narrower at the top.",
            "title": "Sidewall Angle Deg",
            "type": "number"
          }
        },
        "required": [
          "profile",
          "z_min_nm",
          "z_max_nm"
        ],
        "title": "Prism",
        "type": "object"
      },
      "Rectangle": {
        "additionalProperties": false,
        "properties": {
          "kind": {
            "const": "rectangle",
            "default": "rectangle",
            "title": "Kind",
            "type": "string"
          },
          "center_nm": {
            "default": [
              0.0,
              0.0
            ],
            "maxItems": 2,
            "minItems": 2,
            "prefixItems": [
              {
                "type": "number"
              },
              {
                "type": "number"
              }
            ],
            "title": "Center Nm",
            "type": "array"
          },
          "size_nm": {
            "maxItems": 2,
            "minItems": 2,
            "prefixItems": [
              {
                "type": "number"
              },
              {
                "type": "number"
              }
            ],
            "title": "Size Nm",
            "type": "array"
          }
        },
        "required": [
          "size_nm"
        ],
        "title": "Rectangle",
        "type": "object"
      },
      "Structure": {
        "additionalProperties": false,
        "description": "A material region. Later structures override earlier ones where they overlap.",
        "properties": {
          "name": {
            "anyOf": [
              {
                "type": "string"
              },
              {
                "type": "null"
              }
            ],
            "default": null,
            "title": "Name"
          },
          "geometry": {
            "discriminator": {
              "mapping": {
                "ball": "#/$defs/Ball",
                "box": "#/$defs/Box",
                "prism": "#/$defs/Prism"
              },
              "propertyName": "kind"
            },
            "oneOf": [
              {
                "$ref": "#/$defs/Prism"
              },
              {
                "$ref": "#/$defs/Box"
              },
              {
                "$ref": "#/$defs/Ball"
              }
            ],
            "title": "Geometry"
          },
          "material": {
            "discriminator": {
              "mapping": {
                "constant_index": "#/$defs/ConstantIndex",
                "constant_permittivity": "#/$defs/ConstantPermittivity",
                "drude": "#/$defs/Drude",
                "drude_lorentz": "#/$defs/DrudeLorentz",
                "library": "#/$defs/LibraryMaterial",
                "tabulated": "#/$defs/Tabulated"
              },
              "propertyName": "kind"
            },
            "oneOf": [
              {
                "$ref": "#/$defs/ConstantIndex"
              },
              {
                "$ref": "#/$defs/ConstantPermittivity"
              },
              {
                "$ref": "#/$defs/Drude"
              },
              {
                "$ref": "#/$defs/DrudeLorentz"
              },
              {
                "$ref": "#/$defs/Tabulated"
              },
              {
                "$ref": "#/$defs/LibraryMaterial"
              }
            ],
            "title": "Material"
          }
        },
        "required": [
          "geometry",
          "material"
        ],
        "title": "Structure",
        "type": "object"
      },
      "Tabulated": {
        "additionalProperties": false,
        "description": "Tabulated n, k data, linearly interpolated (no extrapolation).",
        "properties": {
          "kind": {
            "const": "tabulated",
            "default": "tabulated",
            "title": "Kind",
            "type": "string"
          },
          "wavelength_nm": {
            "items": {
              "type": "number"
            },
            "title": "Wavelength Nm",
            "type": "array"
          },
          "n_real": {
            "items": {
              "type": "number"
            },
            "title": "N Real",
            "type": "array"
          },
          "n_imag": {
            "items": {
              "type": "number"
            },
            "title": "N Imag",
            "type": "array"
          },
          "source": {
            "anyOf": [
              {
                "type": "string"
              },
              {
                "type": "null"
              }
            ],
            "default": null,
            "description": "Citation / provenance of the data.",
            "title": "Source"
          }
        },
        "required": [
          "wavelength_nm",
          "n_real",
          "n_imag"
        ],
        "title": "Tabulated",
        "type": "object"
      },
      "WavelengthRange": {
        "additionalProperties": false,
        "properties": {
          "start_nm": {
            "exclusiveMinimum": 0,
            "title": "Start Nm",
            "type": "number"
          },
          "stop_nm": {
            "exclusiveMinimum": 0,
            "title": "Stop Nm",
            "type": "number"
          },
          "num": {
            "minimum": 1,
            "title": "Num",
            "type": "integer"
          }
        },
        "required": [
          "start_nm",
          "stop_nm",
          "num"
        ],
        "title": "WavelengthRange",
        "type": "object"
      }
    },
    "additionalProperties": false,
    "description": "A photonic device (waveguides, couplers, gratings, ...) characterised by its S-matrix.",
    "properties": {
      "kind": {
        "const": "device",
        "default": "device",
        "title": "Kind",
        "type": "string"
      },
      "dimension": {
        "default": 3,
        "enum": [
          2,
          3
        ],
        "title": "Dimension",
        "type": "integer"
      },
      "structures": {
        "items": {
          "$ref": "#/$defs/Structure"
        },
        "title": "Structures",
        "type": "array"
      },
      "layout": {
        "anyOf": [
          {
            "$ref": "#/$defs/GdsLayout"
          },
          {
            "type": "null"
          }
        ],
        "default": null
      },
      "background": {
        "discriminator": {
          "mapping": {
            "constant_index": "#/$defs/ConstantIndex",
            "constant_permittivity": "#/$defs/ConstantPermittivity",
            "drude": "#/$defs/Drude",
            "drude_lorentz": "#/$defs/DrudeLorentz",
            "library": "#/$defs/LibraryMaterial",
            "tabulated": "#/$defs/Tabulated"
          },
          "propertyName": "kind"
        },
        "oneOf": [
          {
            "$ref": "#/$defs/ConstantIndex"
          },
          {
            "$ref": "#/$defs/ConstantPermittivity"
          },
          {
            "$ref": "#/$defs/Drude"
          },
          {
            "$ref": "#/$defs/DrudeLorentz"
          },
          {
            "$ref": "#/$defs/Tabulated"
          },
          {
            "$ref": "#/$defs/LibraryMaterial"
          }
        ],
        "title": "Background"
      },
      "domain_center_nm": {
        "default": [
          0.0,
          0.0,
          0.0
        ],
        "maxItems": 3,
        "minItems": 3,
        "prefixItems": [
          {
            "type": "number"
          },
          {
            "type": "number"
          },
          {
            "type": "number"
          }
        ],
        "title": "Domain Center Nm",
        "type": "array"
      },
      "domain_size_nm": {
        "maxItems": 3,
        "minItems": 3,
        "prefixItems": [
          {
            "type": "number"
          },
          {
            "type": "number"
          },
          {
            "type": "number"
          }
        ],
        "title": "Domain Size Nm",
        "type": "array"
      },
      "ports": {
        "items": {
          "$ref": "#/$defs/Port"
        },
        "minItems": 1,
        "title": "Ports",
        "type": "array"
      },
      "wavelengths": {
        "anyOf": [
          {
            "items": {
              "type": "number"
            },
            "type": "array"
          },
          {
            "$ref": "#/$defs/WavelengthRange"
          }
        ],
        "title": "Wavelengths"
      },
      "options": {
        "additionalProperties": {
          "additionalProperties": true,
          "type": "object"
        },
        "title": "Options",
        "type": "object"
      }
    },
    "required": [
      "background",
      "domain_size_nm",
      "ports",
      "wavelengths"
    ],
    "title": "DeviceProblem",
    "type": "object"
  },
  "conventions": "Lightsmith conventions (fixed; changing them needs a schema version bump):\n- Lengths in nm. Wavelengths are vacuum wavelengths in nm.\n- Time dependence exp(-i omega t): absorbing materials have Im(eps) > 0 and Im(n) > 0.\n- Cross sections in nm^2; efficiencies Q = C / (pi r_eq^2), r_eq = volume-equivalent radius of all particles.\n- layer_stack / periodic: layers listed from the superstrate (incidence side) to the substrate; light travels +z.\n  R is measured in the superstrate, T in the substrate.\n- mode: cross-section in the xy plane, propagation along +z.\n- device: ports are planes whose normal is the axis where size_nm is zero; direction is into the device.\n- problem.options[<method or backend name>] holds solver options, validated by that backend.\n- Materials: {\"kind\": \"constant_index\", \"n_real\": .., \"n_imag\": ..}, {\"kind\": \"library\", \"name\": \"Au\"},\n  drude, drude_lorentz, tabulated, constant_permittivity. FDTD needs dispersive models (fit_drude_lorentz).\n- Results carry provenance and warnings: read the warnings before trusting the numbers.\n",
  "backends": [
    {
      "name": "lightsmith-eme",
      "method": "eme",
      "available": true,
      "gpu": false,
      "auto_rank": 0
    },
    {
      "name": "lightsmith-bpm",
      "method": "bpm",
      "available": true,
      "gpu": true,
      "auto_rank": 1
    },
    {
      "name": "lightsmith-fdfd",
      "method": "fdfd",
      "available": true,
      "gpu": true,
      "auto_rank": 2
    },
    {
      "name": "lightsmith-fdtd",
      "method": "fdtd",
      "available": true,
      "gpu": true,
      "auto_rank": 3
    }
  ],
  "example": {
    "kind": "device",
    "dimension": 2,
    "structures": [
      {
        "geometry": {
