            "default": 20.0,
            "description": "Cells per shortest wavelength inside the optically densest material (|n|).",
            "minimum": 6,
            "title": "Cells Per Wavelength",
            "type": "number"
          },
          "cells_per_radius": {
            "anyOf": [
              {
                "minimum": 2,
                "type": "number"
              },
              {
                "type": "null"
              }
            ],
            "default": null,
            "description": "Minimum cells across the smallest particle half-extent. Default 10, or 20 when a material has Re(eps) < 0 in the band (plasmonic; ~2.5% peak-height error at 20).",
            "title": "Cells Per Radius"
          },
          "pml_cells": {
            "anyOf": [
              {
                "minimum": 4,
                "type": "integer"
              },
              {
                "type": "null"
              }
            ],
            "default": null,
            "description": "CPML thickness in cells. Default: 10, 16 with a substrate (steep waves in the substrate need the thicker layer), 12 for devices.",
            "title": "Pml Cells"
          },
          "pml_kappa": {
            "default": 1.0,
            "description": "CPML kappa_max (>1 damps evanescent fields faster).",
            "minimum": 1,
            "title": "Pml Kappa",
            "type": "number"
          },
          "padding_nm": {
            "anyOf": [
              {
                "minimum": 0,
                "type": "number"
              },
              {
                "type": "null"
              }
            ],
            "default": null,
            "description": "Gap between the particles' bounding box (periodic: the stack) and the TFSF box (plane). Default 4 cells, and for scattering at least 3% of the longest wavelength in the medium.",
            "title": "Padding Nm"
          },
          "pml_gap_nm": {
            "anyOf": [
              {
                "minimum": 0,
                "type": "number"
              },
              {
                "type": "null"
              }
            ],
            "default": null,
            "description": "Gap between the flux monitors and the CPML. Scattering: 4 cells, at least 3% of the longest wavelength in the medium; periodic: 3 decay lengths of the slowest evanescent diffraction order, 0.25-1.5 wavelengths.",
            "title": "Pml Gap Nm"
          },
          "courant": {
            "default": 0.95,
            "description": "Time step as a fraction of the 3D Courant limit.",
            "exclusiveMinimum": 0,
            "maximum": 1,
            "title": "Courant",
            "type": "number"
          },
          "run_time_fs": {
            "anyOf": [
              {
                "exclusiveMinimum": 0,
                "type": "number"
              },
              {
                "type": "null"
              }
            ],
            "default": null,
            "description": "Fixed simulated time in fs. Disables the decay shutoff.",
            "title": "Run Time Fs"
          },
          "decay_by": {
            "default": 0.00001,
            "description": "Stop when the field energy on the flux monitors has fallen below this fraction of its peak (after the pulse has passed).",
            "exclusiveMaximum": 1,
            "exclusiveMinimum": 0,
            "title": "Decay By",
            "type": "number"
          },
          "max_time_fs": {
            "default": 2000.0,
            "description": "Hard cap on simulated time in fs (high-Q resonances need ps).",
            "exclusiveMinimum": 0,
            "title": "Max Time Fs",
            "type": "number"
          },
          "precision": {
            "default": "auto",
            "description": "auto = single on GPU, double on CPU (and over an absorbing substrate).",
            "enum": [
              "auto",
              "single",
              "double"
            ],
            "title": "Precision",
            "type": "string"
          },
          "subpixel": {
            "default": true,
            "description": "Anisotropic subpixel smoothing at interfaces (dispersive too). False means staircase. Superseded by mesh_refinement when that is set.",
            "title": "Subpixel",
            "type": "boolean"
          },
          "mesh_refinement": {
            "anyOf": [
              {
                "enum": [
                  "staircase",
                  "volume_average",
                  "subpixel",
                  "conformal"
                ],
                "type": "string"
              },
              {
                "type": "null"
              }
            ],
            "default": null,
            "description": "Interface treatment. staircase: the medium at each field position. volume_average: <eps> over the cell. subpixel: diagonal anisotropic averaging (Farjadpour 2006). conformal: the full tensor with off-diagonal terms (Kottke 2008); at interfaces with a dispersive medium (metals) it is applied at grid vertices as a sum of passive congruences. Default: conformal (device problems: subpixel, so that the port modes are exact), or staircase when subpixel is False.",
            "title": "Mesh Refinement"
          },
          "subpixel_samples": {
            "default": 8,
            "description": "Supersamples per axis for interface cells.",
            "maximum": 24,
            "minimum": 2,
            "title": "Subpixel Samples",
            "type": "integer"
          },
          "dft_stride": {
            "anyOf": [
              {
                "minimum": 1,
                "type": "integer"
              },
              {
                "type": "null"
              }
            ],
            "default": null,
            "description": "Time steps between DFT samples. Default: from the source bandwidth (aliasing-safe).",
            "title": "Dft Stride"
          },
          "symmetry": {
            "default": "auto",
            "description": "Scattering: use mirror planes through the particles' centre when the particles and the plane wave allow them (PEC/PMC planes, chosen from the polarisation; 2x or 4x smaller runs, same results). The provenance reports the planes used.",
            "enum": [
              "auto",
              "off"
            ],
            "title": "Symmetry",
            "type": "string"
          },
          "polarization": {
            "anyOf": [
              {
                "enum": [
                  "te",
                  "tm"
                ],
                "type": "string"
              },
              {
                "type": "null"
              }
            ],
            "default": null,
            "description": "2D device problems: the port modes' polarisation, te = E in the xy plane (default, as FDFD and EME), tm = E along z. The two do not couple in a z-invariant device.",
            "title": "Polarization"
          },
          "grid": {
            "default": "uniform",
            "description": "Scattering and devices: 'auto' grades the grid (non-uniform per axis): the base spacing from the host medium and cells_per_wavelength, refined inside each particle's bounding box (plus a margin) to the spacing its material and size need (cells_per_wavelength in the particle, cells_per_radius), with a bounded growth ratio (grading_ratio) in between. Far fewer cells for small, high-index or metal particles.",
            "enum": [
              "uniform",
              "auto"
            ],
            "title": "Grid",
            "type": "string"
          },
          "mesh_override": {
            "description": "Scattering and devices: refinement boxes (mesh override regions); the grid takes each box's spacing inside it and grades to the base spacing (spacing_nm, or the automatic spacing) around it. Combine with grid='auto' or use alone.",
            "items": {
              "$ref": "#/$defs/MeshOverride"
            },
            "title": "Mesh Override",
            "type": "array"
          },
          "background_cells_per_wavelength": {
            "default": 60.0,
            "description": "grid='auto': base cells per shortest wavelength in the background. A change of cell size h reflects ~(k h)^2 / 16 of a wave however gently it is graded (the grid's impedance depends on h), so the coarse cells must stay fine: 60 keeps that below 0.07%.",
            "minimum": 10,
            "title": "Background Cells Per Wavelength",
            "type": "number"
          },
          "grading_ratio": {
            "default": 1.25,
            "description": "Largest growth of the cell width from one cell to the next on a graded grid.",
            "maximum": 1.5,
            "minimum": 1.05,
            "title": "Grading Ratio",
            "type": "number"
          },
          "cuda_graphs": {
            "default": true,
            "description": "Replay time steps as CUDA graphs on PyTorch CUDA (much faster).",
            "title": "Cuda Graphs",
            "type": "boolean"
          },
          "max_cells": {
            "default": 300000000,
            "description": "Refuse grids larger than this.",
            "minimum": 1,
            "title": "Max Cells",
            "type": "integer"
          }
        },
        "title": "FDTDOptions",
        "type": "object"
      }
    }
  ]
}

